import{validateRelease}from'./release-core.mjs';
try{const response=await fetch(new URL('latest.json',location.href),{cache:'no-store'});if(!response.ok)throw Error();const raw=await response.json();const release=validateRelease(raw,{allowUnpublished:true});document.querySelector('#version').textContent='v'+release.version;document.querySelector('#notes').textContent=release.notes||'这个版本已准备就绪。';document.querySelector('#release-meta').textContent=`版本 ${release.version} · Windows 10 / 11 · ${(release.size/1048576).toFixed(1)} MB`;document.querySelector('#checksum').textContent='SHA256 · '+release.sha256;if(raw.published!==false){const link=document.querySelector('#download');link.href=release.url;link.classList.remove('download-disabled');link.setAttribute('aria-disabled','false');link.replaceChildren(document.createTextNode('下载 MeTN  '+release.version+'  ↓'));}}catch{document.querySelector('#release-meta').textContent='版本信息暂时无法读取，请稍后再试。';document.querySelector('#notes').textContent='发布信息更新中。';}
